template <bool Purposed, class Result>
PriorityRequest<Purposed, Result>& PriorityRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

template <bool Purposed, class Result>
PlatformRequest<Purposed, Result>& PlatformRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

template <bool Purposed, class Result>
SampleItemRequest<Purposed, Result>&
SampleItemRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    PriorityRequest<false> prioritiesMinimal() const {
        return PriorityRequest<false>(binding_.get(), true);
    }

    PriorityRequest<false> priorities() const {
        return PriorityRequest<false>(binding_.get());
    }

    PriorityRequest<false> prioritiesWithChildren() const {
        return PriorityRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    PlatformRequest<false> platformsMinimal() const {
        return PlatformRequest<false>(binding_.get(), true);
    }

    PlatformRequest<false> platforms() const {
        return PlatformRequest<false>(binding_.get());
    }

    PlatformRequest<false> platformsWithChildren() const {
        return PlatformRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    SampleItemRequest<false> sampleItemsMinimal() const {
        return SampleItemRequest<false>(binding_.get(), true);
    }

    SampleItemRequest<false> sampleItems() const {
        return SampleItemRequest<false>(binding_.get());
    }

    SampleItemRequest<false> sampleItemsWithChildren() const {
        return SampleItemRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
